$status = function_exists('opcache_get_status') ? opcache_get_status(false) : null;
$directives = [];
foreach (['opcache.enable_cli','opcache.jit_buffer_size','opcache.jit','extension_dir','short_open_tag','memory_limit'] as $key) {
    $directives[$key] = ini_get($key);
}
echo json_encode([
    'version' => PHP_VERSION,
    'loaded_zend_extensions' => get_loaded_extensions(true),
    'opcache_module_loaded' => extension_loaded('Zend OPcache'),
    'opcache_status' => $status,
    'ini_directives' => $directives,
    'loaded_ini_file' => php_ini_loaded_file(),
    'scanned_ini_files' => php_ini_scanned_files(),
], JSON_PRETTY_PRINT | JSON_THROW_ON_ERROR), "\n";
